update public.questions set body = 'In a certain code, CAT is written as DCW and DOG as EQJ. How is HEN written in that code?', body_hi = 'एक निश्चित कूट में CAT को DCW और DOG को EQJ लिखा जाता है। उसी कूट में HEN को कैसे लिखा जाएगा?', question_data = '{"fixed_option_order": true, "craft": "application", "csat_set": "csat-l2-t04", "csat_order": 25}'::jsonb, options = '[{"id": "a", "body": "GCK", "body_hi": "GCK", "isCorrect": false}, {"id": "b", "body": "HFP", "body_hi": "HFP", "isCorrect": false}, {"id": "c", "body": "IFO", "body_hi": "IFO", "isCorrect": false}, {"id": "d", "body": "IGQ", "body_hi": "IGQ", "isCorrect": true}]'::jsonb, explanation = 'Compare letter by letter: C → D (+1), A → C (+2), T → W (+3), and D → E, O → Q, G → J in the same way: the first letter moves one place, the second two and the third three. HEN becomes H + 1 = I, E + 2 = G, N + 3 = Q: IGQ. IFO moves every letter by one place; HFP starts the steps at +0; GCK moves the letters backwards instead of forwards.', explanation_hi = 'अक्षर-दर-अक्षर तुलना कीजिए: C → D (+1), A → C (+2), T → W (+3), और इसी तरह D → E, O → Q, G → J: पहला अक्षर एक स्थान, दूसरा दो और तीसरा तीन स्थान खिसकता है। HEN बनता है H + 1 = I, E + 2 = G, N + 3 = Q: IGQ। IFO हर अक्षर को एक ही स्थान खिसकाता है; HFP कदमों को +0 से शुरू करता है; GCK अक्षरों को आगे के बजाय पीछे ले जाता है।' where concept_group_id = 'csat-l2-t04-lr-cd-each-letter-one-place-further' and status = 'draft' returning concept_group_id;
